import './globals.css';
import { Inter } from 'next/font/google';
import Link from 'next/link';
import { usePathname } from 'next/navigation';

const inter = Inter({ subsets: ['latin'] });

export default function RootLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const isActive = pathname === '/finance';

  return (
    <html lang="en">
      <head>
        <meta charSet="UTF-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
        <title>Finance OS</title>
        <link rel="icon" href="/favicon.ico" />
      </head>
      <body className={inter.className}>
        <header className="bg-racing-red text-white shadow-neon-red">
          <span className="status-dot"></span>
          <h1>FINANCE OS</h1>
          <nav>
            {tabs.map(tab => (
              <Link
                key={tab.href}
                href={tab.href}
                className={`${isActive ? 'bg-racing-red text-white shadow-neon-red' : 'text-gray-400 hover:text-white hover:bg-carbon-light'}`}
              >
                {tab.name}
              </Link>
            ))}
            <Link href="/finance/settings">Settings</Link>
          </nav>
        </header>
        <main>{children}</main>
      </body>
    </html>
  );
}

const tabs = [
  { name: 'Overview', href: '/finance' },
  { name: 'Investments', href: '/finance/investments' },
  { name: 'Debt', href: '/finance/debt' },
  { name: 'Tracker', href: '/finance/tracker' },
  { name: 'Learning', href: '/finance/learning' },
];
